function normalizarDocumentoImportacao(valor) {
  return String(valor || "").replace(/\D/g, "");
}

function importarClientesDoRelatorio() {
  try {
    const existentes = Array.isArray(clientes) ? clientes : [];
    const porDocumento = new Set(
      existentes.map(c => normalizarDocumentoImportacao(c.cpfCnpj)).filter(Boolean)
    );
    const porCodigo = new Set(
      existentes.map(c => String(c.codigo || "").trim()).filter(Boolean)
    );
    let adicionados = 0;
    let ignorados = 0;

    CLIENTES_IMPORTACAO.forEach(function(c) {
      const documento = normalizarDocumentoImportacao(c.cpfCnpj);
      const codigo = String(c.codigo || "").trim();

      if ((documento && porDocumento.has(documento)) ||
          (codigo && porCodigo.has(codigo))) {
        ignorados++;
        return;
      }

      clientes.push({
        ...c,
        id: Date.now() + Math.floor(Math.random() * 1000000)
      });

      if (documento) porDocumento.add(documento);
      if (codigo) porCodigo.add(codigo);
      adicionados++;
    });

    localStorage.setItem("clientesCRM", JSON.stringify(clientes));
    if (typeof mostrarClientes === "function") mostrarClientes();
    if (typeof carregarClientesSelect === "function") carregarClientesSelect();

    localStorage.setItem("multipla_clientes_importados_20261014_v3", "ok");
    console.log(
      "Múltipla Cotação PRO: " + adicionados +
      " clientes adicionados; " + ignorados + " duplicados ignorados."
    );
  } catch (erro) {
    console.error("Erro na importação dos clientes:", erro);
  }
}

if (!localStorage.getItem("multipla_clientes_importados_20261014_v3")) {
  importarClientesDoRelatorio();
}
